<script lang="ts">
 import {onMount} from 'svelte';
 import {setLanguage} from '$lib/i18n/language';
 import ThemeSelector from '$lib/application/ThemeSelector.svelte';
 import MeshtasticChannels from '$lib/radio/MeshtasticChannels.svelte';
 import ConversationRow from '$lib/chat/ConversationRow.svelte';
 import TextForwardDialog,{type ForwardText} from '$lib/chat/TextForwardDialog.svelte';
 import {nativeChannelToken,nativeMessageKey,appendChannelMessage,removeNativeMessages,nativeChatEntry,visibleNativeChannels,type NativeChannels,type NativeChannel,type ChannelMessage} from '$lib/radio/native-channels';
 onMount(()=>setLanguage('ru'));
 const start=new Date(2026,10,10,16).getTime();
 let data=$state<NativeChannels>({enabled:true,configured:true,historyLimit:100,channels:[
  {node:100,key:'a'.repeat(64),name:'Город',boardName:'🐇 Дом',index:0,public:true,encryption:'default',signature:false,unread:2,messages:Array.from({length:22},(_,i)=>({id:i+1,from:i%3?200:100,name:i%3?'🐈 Кот':'🐇 Дом',text:i===21?'Можно отправить маршрут?':i===20?'Да, встречаемся в субботу':`Сообщение ${i+1}`,timestamp:start+i*6000000,outgoing:i%3===0,status:i===18?'failed':'mesh',...(i===18?{failure:{source:'queue' as const,code:32}}:{})}))},
  {node:100,key:'b'.repeat(64),name:'Поход',boardName:'🐇 Дом',index:1,public:false,encryption:'custom',signature:false,unread:0,messages:[],draft:''},
  {node:300,key:'c'.repeat(64),name:'Сохранённый',boardName:'🦊 Дача',index:0,public:false,encryption:'custom',signature:false,unread:1,messages:[{id:1,from:400,name:'🦊 Дача',text:'История другой платы',timestamp:start,outgoing:false,status:'accepted'}]},
  {node:300,key:'d'.repeat(64),name:'Пустой старый',index:1,public:true,signature:false,unread:0,messages:[]}
 ]});
 let selected=$state(`100:${'a'.repeat(64)}`),connected=$state(true),busy=$state(false),narrow=$state(false),forward=$state<ForwardText[]|null>(null),note=$state(''),fail=$state(false),forwardDone=$state(0),initialUnread=$state(2);
 const live=$derived(data.channels.filter(c=>c.node===100).map(nativeChannelToken));
 const listed=$derived(visibleNativeChannels(data,connected?100:undefined,live));
 function select(c:NativeChannel){initialUnread=c.unread;selected=nativeChannelToken(c);}
 function draft(c:NativeChannel,text:string,replyId?:number){data={...data,channels:data.channels.map(x=>nativeChannelToken(x)===nativeChannelToken(c)?{...x,draft:text,replyId}:x)};}
 async function send(c:NativeChannel,text:string,options?:{replyId?:number}){busy=true;try{if(fail)throw Error('Тестовая ошибка сохранения');data=appendChannelMessage(data,c.key,c.node,{id:Date.now()%0xffffffff,from:c.node,name:'🐇 Дом',text,timestamp:Date.now(),outgoing:true,status:'accepted',replyId:options?.replyId},true);}finally{busy=false;}}
 async function remove(c:NativeChannel,ids:string[]){if(fail)throw Error('Тестовая ошибка сохранения');data=removeNativeMessages(data,c,ids);}
</script>
<svelte:head><title>Локальная проверка радиочата</title></svelte:head>
<div class="review" class:narrow><p>Локальная проверка настоящих компонентов · данные примера · радиопередачи нет</p><div class="controls"><ThemeSelector/><button onclick={()=>setLanguage('ru')}>Русский</button><button onclick={()=>setLanguage('en')}>English</button><label><input type="checkbox" bind:checked={narrow}/> Узкий экран</label><label><input type="checkbox" bind:checked={connected}/> Плата подключена</label><label><input type="checkbox" checked={data.showAll} onchange={e=>data={...data,showAll:e.currentTarget.checked}}/> Все сохранённые радиоканалы</label><label><input type="checkbox" bind:checked={fail}/> Ошибка сохранения</label><a href="/">Приложение</a></div>
<div class="layout"><nav>{#each listed as c (nativeChannelToken(c))}<ConversationRow accountId={nativeChannelToken(c)} name={c.name} conversation={{peerAddress:'',messages:[],unread:c.unread,draft:'',connection:'offline',error:'',sending:false,contact:'accepted'}} active={selected===nativeChannelToken(c)} onOpen={()=>select(c)} radio={{encryption:c.encryption,preview:c.messages.at(-1)?.text||'Пока нет сообщений'}}/>{/each}</nav><main>{#key selected}<MeshtasticChannels {data} {selected} {live} {connected} {busy} board="🐇 Дом" link="https://example.com/#contact/test" {initialUnread} {forwardDone} onDraft={draft} onDelete={remove} onSend={send} onSettings={()=>note='Настройки LoRa открываются в приложении.'} onBack={()=>note='Возврат к списку чатов.'} onSignature={async(c,value)=>{data={...data,channels:data.channels.map(x=>nativeChannelToken(x)===nativeChannelToken(c)?{...x,signature:value}:x)};}} onBottom={value=>{if(value)data={...data,channels:data.channels.map(c=>nativeChannelToken(c)===selected&&c.unread?{...c,unread:0}:c)};}} onForward={(c,messages)=>forward=messages.map(m=>({key:nativeMessageKey(m),text:m.text,source:c.name}))}/>{/key}</main></div>{#if note}<p role="status">{note}</p>{/if}
{#if forward}<TextForwardDialog messages={forward} targets={[{id:'chat:test',name:'Александра',radio:false},{id:'radio:test',name:'Поход',radio:true}]} onSend={async()=>{if(fail)throw Error('Тестовая ошибка');note='Пример пересылки завершён.';}} onClose={()=>forward=null} onComplete={()=>{forward=null;forwardDone++;}}/>{/if}</div>
<style>.review{max-width:1100px;width:100%;margin:auto}.review.narrow{max-width:390px}.review>p{font-size:12px;color:var(--muted)}.controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px}.controls label{font-size:12px}.layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:16px;height:78dvh;min-height:500px}.layout nav{display:flex;flex-direction:column;gap:4px;min-width:0}.layout nav :global(.conversation-row){width:100%;text-align:left;border:1px solid var(--line);border-radius:10px;padding:8px;background:var(--surface)}main{min-height:0;min-width:0}.narrow .layout{display:flex;flex-direction:column;height:auto}.narrow nav{max-height:180px;overflow:auto}.narrow main{height:650px}@media(max-width:700px){.layout{display:flex;flex-direction:column;height:auto}.layout nav{max-height:180px;overflow:auto}main{height:650px}}</style>
